  )
  and exists (
    select
      "asset_face"."assetId"
    from
      "asset_face"
    where
      "asset_face"."assetId" = "asset"."id"
      and "asset_face"."deletedAt" is null
      and "asset_face"."isVisible" = $7
      and "asset_face"."personGroupId" = any ($8::uuid[])
    group by
      "asset_face"."assetId"
    having
      count(distinct "asset_face"."personGroupId") = $9
