  and (
    "asset"."ownerId" = $6::uuid
    or "asset"."deletedAt" is null
  )
  and true
order by
  (
    (smart_search.embedding <=> $7) - $8 * coalesce(
      greatest(
        0,
        $9 - (
          select
            embedding <=> $10
          from
            smart_search_description
          where
            "assetId" = asset.id
        )
      ),
      0
    )
  ),
  "asset"."id" asc
limit
  $11
offset
  $12
commit

