-- SearchRepository.searchFacets
with
  matched as materialized (
    (
      select
        "asset"."id",
        "asset"."ownerId",
        "asset"."type",
        "asset"."isFavorite",
        "asset"."fileCreatedAt"
      from
        "asset"
      where
        "asset"."libraryScope" in ($1, $2)
        and (
          not exists (
            select
              1
            from
              asset_lock
            where
              asset_lock."assetId" = "asset"."id"
          )
          or "asset"."ownerId" = $3::uuid
        )
        and "asset"."fileCreatedAt" >= $4
        and "asset"."ownerId" = any ($5::uuid[])
        and "asset"."deletedAt" is null
    )
  ),
  facet_rows as (
    select
      $6::text as field,
      m.type::text as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
    group by
      2
    union all
    select
      $7::text as field,
      (
        m."isFavorite"
        and m."ownerId" = $8::uuid
      )::text as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
    group by
      2
    union all
    select
      $9::text as field,
      case
        when e.rating between 1 and 5 then e.rating::text
        else 'unrated'
      end as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      left join asset_exif e on e."assetId" = m.id
    group by
      2
    union all
    select
      $10::text as field,
      nullif(trim("e"."city"), '') as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join asset_exif e on e."assetId" = m.id
    where
      nullif(trim("e"."city"), '') is not null
      and true
    group by
      2
    union all
    select
      $11::text as field,
      nullif(trim("e"."country"), '') as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join asset_exif e on e."assetId" = m.id
    where
      nullif(trim("e"."country"), '') is not null
      and true
    group by
      2
    union all
    select
      $12::text as field,
      nullif(trim("e"."make"), '') as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join asset_exif e on e."assetId" = m.id
    where
      nullif(trim("e"."make"), '') is not null
      and true
    group by
      2
    union all
    select
      $13::text as field,
      nullif(trim("e"."model"), '') as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join asset_exif e on e."assetId" = m.id
    where
      nullif(trim("e"."model"), '') is not null
      and true
    group by
      2
    union all
    select
      $14::text as field,
      nullif(trim("e"."lensModel"), '') as value,
      null::text as label,
      count(*) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join asset_exif e on e."assetId" = m.id
    where
      nullif(trim("e"."lensModel"), '') is not null
      and true
    group by
      2
    union all
    select
      $15::text as field,
      f."personGroupId"::text as value,
      max(nullif(p.name, '')) as label,
      count(distinct m.id) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join asset_face f on f."assetId" = m.id
      and f."deletedAt" is null
      and f."isVisible" is true
      inner join person p on p."personGroupId" = f."personGroupId"
      and p."ownerId" = $16::uuid
      and not p."isHidden"
    where
      not (f."personGroupId" = any ($17::uuid[]))
    group by
      f."personGroupId"
    union all
    select
      $18::text as field,
      t.id::text as value,
      max(t.value) as label,
      count(distinct m.id) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join tag_asset ta on ta."assetId" = m.id
      inner join tag_closure tc on tc.id_descendant = ta."tagId"
      inner join tag t on t.id = tc.id_ancestor
      and t."userId" = $19::uuid
    where
      not exists (
        select
          1
        from
          tag_closure
        where
          tag_closure.id_descendant = "t"."id"
          and tag_closure.id_ancestor = any ($20::uuid[])
      )
    group by
      t.id
    union all
    select
      $21::text as field,
      pet.id::text as value,
      max(nullif(pet.name, '')) as label,
      count(distinct m.id) as count,
      (
        array_agg(
          m.id
          order by
            m."fileCreatedAt" desc,
            m.id desc
        )
      ) [1]::text as cover
    from
      matched m
      inner join pet_observation po on po."assetId" = m.id
      and po.state = $22
      inner join pet on pet.id = po."petId"
      and pet."ownerId" = $23::uuid
      and not pet."isHidden"
    where
      not (pet.id = any ($24::uuid[]))
    group by
      pet.id
    union all
    select
      'total'::text as field,
      null::text as value,
      null::text as label,
      count(*) as count,
      null::text as cover
    from
      matched
  ),
  ranked as (
    select
      *,
      row_number() over (
        partition by
          field
        order by
          count desc,
          value asc
      ) as rank
    from
      facet_rows
  )
select
  field,
  value,
  label,
  count,
  cover
from
  ranked
where
  rank <= $25
order by
  field,
  rank

