-- SearchRepository.searchHistogram
with
  matched as (
    (
      select
        "asset"."localDateTime"
      from
        "asset"
      where
        "asset"."libraryScope" in ($1, $2)
        and (
          not exists (
            select
              1
            from
              asset_lock
            where
              asset_lock."assetId" = "asset"."id"
          )
          or "asset"."ownerId" = $3::uuid
        )
        and "asset"."fileCreatedAt" >= $4
        and "asset"."ownerId" = any ($5::uuid[])
        and "asset"."deletedAt" is null
    )
  )
select
  to_char(
    date_trunc(
      'month',
      matched."localDateTime" at time zone 'UTC'
    ),
    'YYYY-MM-DD'
  ) as date,
  count(*) as count
from
  matched
group by
  1
order by
  1

