        and (
          "asset"."ownerId" = any ($3::uuid[])
          and (
            "asset"."ownerId" = $4::uuid
            or (
              "asset"."deletedAt" is null
              and "asset"."visibility" in ('timeline', 'hidden')
            )
          )
        )
        and (
          not exists (
            select
              1
            from
              asset_lock
            where
              asset_lock."assetId" = "asset"."id"
          )
          or "asset"."ownerId" = $5::uuid
        )
        and (
          "asset"."ownerId" = $6::uuid
          or "asset"."deletedAt" is null
        )
        and true
    )
  )
select
  to_char(
    date_trunc('day', matched."localDateTime" at time zone 'UTC'),
    'YYYY-MM-DD'
  ) as date,
  count(*) as count
from
  matched
group by
  1
order by
  1

-- SearchRepository.searchSmartCount
select
  count(*) as total
from
  (
    (
      select
        "asset"."id"
      from
        "asset"
        inner join "smart_search" on "asset"."id" = "smart_search"."assetId"
      where
        "asset"."libraryScope" in ($1, $2)
        and (
          not exists (
            select
              1
            from
              asset_lock
            where
              asset_lock."assetId" = "asset"."id"
          )
          or "asset"."ownerId" = $3::uuid
        )
        and "asset"."fileCreatedAt" >= $4
        and "asset"."ownerId" = any ($5::uuid[])
        and "asset"."deletedAt" is null
      limit
        $6
    )
  ) capped

-- SearchRepository.searchSmartCountV3
select
  count(*) as total
from
  (
    (
      select
        "asset"."id"
      from
        "asset"
        left join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
        inner join "smart_search" on "asset"."id" = "smart_search"."assetId"
      where
        "asset"."libraryScope" in ($1, $2)
        and (
          "asset"."ownerId" = any ($3::uuid[])
          and (
            "asset"."ownerId" = $4::uuid
            or (
              "asset"."deletedAt" is null
              and "asset"."visibility" in ('timeline', 'hidden')
            )
          )
        )
        and (
          not exists (
            select
              1
            from
              asset_lock
            where
              asset_lock."assetId" = "asset"."id"
          )
          or "asset"."ownerId" = $5::uuid
        )
        and (
          "asset"."ownerId" = $6::uuid
          or "asset"."deletedAt" is null
        )
        and true
      limit
        $7
    )
  ) capped
